//! Compare the scripted writer projection against twelve retained original rows.
use spore_core::cell_restore_writer_gate_v1::project;
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut a=std::env::args().skip(1);let b=std::fs::read(a.next().expect("native rows")).unwrap();let obj=u32::from_str_radix(&a.next().expect("synthetic object address"),16).unwrap();assert_eq!(b.len(),480);for i in 0..12{let k=i%6;let x=project(k!=0,if k>=2{Some((obj,0xabcdef00))}else{None},if k>=2{Some(k!=3)}else{None},if k==0||k==3{None}else{Some(k!=5)},true).unwrap();let r=&b[i*40..(i+1)*40];assert_eq!((w(r,0),w(r,4),w(r,8),w(r,12),w(r,16),w(r,20),w(r,24)),(u32::from(x.returned),x.words.len() as u32,x.words.first().copied().unwrap_or(0),x.words.get(1).copied().unwrap_or(0),x.after,x.end,x.getters));let fp=w(r,28);assert_eq!(fp&0xffff,if i>=6{0x37f}else{0x27f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,32)&!0x3f,0x1f80);assert_eq!(w(r,36),0xa5a5a5a5);}println!("matched twelve source writer/key rows; synthetic callbacks and identity admitted");}
